def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Recolor uniform rectangular areas immediately to the right of a
    # non-background pattern, using the pattern's height as the patch height.
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(r.count(x) for r in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0 = min(y for y,x in comp); r1 = max(y for y,x in comp)
            c1 = max(x for y,x in comp)
            height = r1-r0+1
            # Patch immediately to the right, extending to the edge.
            if c1 + 1 < w:
                for y in range(r0, min(h, r0+height)):
                    for x in range(c1+1, w):
                        if grid[y][x] == bg:
                            out[y][x] = 1
    return out
